def seed_projects(apps, schema_editor):
    database = schema_editor.connection.alias
    Project = apps.get_model("contact", "Project")
    ProjectRepositoryLink = apps.get_model("contact", "ProjectRepositoryLink")

    Project.objects.using(database).bulk_create(
        [
            Project(
                slug=slug,
                title=title,
                category=category,
                description=description,
                technologies=technologies,
                live_url=live_url,
                display_order=index,
            )
            for index, (
                slug,
                title,
                category,
                description,
                technologies,
                live_url,
            ) in enumerate(PROJECT_DATA, start=1)
        ]
    )

    repository_links = ProjectRepositoryLink.objects.using(database).values_list(
        "project_slug",
        "repository_url",
    )
    for slug, repository_url in repository_links:
        Project.objects.using(database).filter(slug=slug).update(
            repository_url=repository_url
        )


def restore_repository_links(apps, schema_editor):
    database = schema_editor.connection.alias
    Project = apps.get_model("contact", "Project")
    ProjectRepositoryLink = apps.get_model("contact", "ProjectRepositoryLink")

    ProjectRepositoryLink.objects.using(database).bulk_create(
        [
            ProjectRepositoryLink(
                project_slug=project.slug,
                repository_url=project.repository_url,
            )
            for project in Project.objects.using(database)
            .exclude(repository_url="")
            .iterator()
            if len(project.slug) <= 40
        ],
        ignore_conflicts=True,
    )


